<?php
 namespace QQWorld\UrlRewrite\Test\Unit\Block\Plugin\Store\Switcher; use QQWorld\Framework\TestFramework\Unit\Helper\ObjectManager; class SetRedirectUrlTest extends \PHPUnit\Framework\TestCase { protected $unit; protected $urlFinder; protected $urlHelper; protected $switcher; protected $store; protected $request; protected $urlBuilder; protected function setUp() { $this->store = $this->createMock(\QQWorld\Store\Model\Store::class); $this->request = $this->createMock(\QQWorld\Framework\App\Request\Http::class); $this->urlBuilder = $this->createMock(\QQWorld\Framework\UrlInterface::class); $this->urlHelper = $this->createMock(\QQWorld\Framework\Url\Helper\Data::class); $this->urlFinder = $this->createMock(\QQWorld\UrlRewrite\Model\UrlFinderInterface::class); $this->switcher = $this->createMock(\QQWorld\Store\Block\Switcher::class); $this->unit = (new ObjectManager($this))->getObject( \QQWorld\UrlRewrite\Block\Plugin\Store\Switcher\SetRedirectUrl::class, [ 'urlFinder' => $this->urlFinder, 'urlHelper' => $this->urlHelper, 'urlBuilder' => $this->urlBuilder, 'request' => $this->request, ] ); } public function testNoUrlRewriteForSpecificStoreOnGetTargetStorePostData() { $this->request->expects($this->once())->method('getPathInfo')->willReturn('path'); $this->urlFinder->expects($this->once())->method('findOneByData')->willReturn(null); $this->urlHelper->expects($this->never())->method('getEncodedUrl'); $this->assertEquals( [$this->store, []], $this->unit->beforeGetTargetStorePostData($this->switcher, $this->store, []) ); } public function testTrimPathInfoForGetTargetStorePostData() { $this->request->expects($this->once())->method('getPathInfo')->willReturn('path/with/trim/'); $this->store->expects($this->once())->method('getId')->willReturn(1); $this->urlFinder->expects($this->once())->method('findOneByData') ->with([ \QQWorld\UrlRewrite\Service\V1\Data\UrlRewrite::TARGET_PATH => 'path/with/trim', \QQWorld\UrlRewrite\Service\V1\Data\UrlRewrite::STORE_ID => 1, ]) ->willReturn(null); $this->urlHelper->expects($this->never())->method('getEncodedUrl'); $this->assertEquals( [$this->store, []], $this->unit->beforeGetTargetStorePostData($this->switcher, $this->store, []) ); } public function testGetTargetStorePostData() { $urlRewrite = $this->createMock(\QQWorld\UrlRewrite\Service\V1\Data\UrlRewrite::class); $urlRewrite->expects($this->once())->method('getRequestPath')->willReturn('path'); $this->request->expects($this->once())->method('getPathInfo')->willReturn('path'); $this->urlFinder->expects($this->once())->method('findOneByData')->willReturn($urlRewrite); $this->urlHelper->expects($this->once())->method('getEncodedUrl')->willReturn('encoded-path'); $this->urlBuilder->expects($this->once())->method('getUrl')->willReturn('path'); $this->assertEquals( [$this->store, [\QQWorld\Framework\App\ActionInterface::PARAM_NAME_URL_ENCODED => 'encoded-path']], $this->unit->beforeGetTargetStorePostData($this->switcher, $this->store, []) ); } } 